"""Shared wording for the unit-5 explanations (explain_u5.py and explain_u5_e5 ... explain_u5_e10).
Steps starting with '## ' are stage headings; every other step is numbered in the review."""

POW = r"قاعدة القوة في التكامل: $\displaystyle\int x^n\,dx=\frac{x^{n+1}}{n+1}+C$ (نزيد الأس واحدًا ونقسم على الأس الجديد)، بشرط $n\neq-1$"
SUB = r"خطوات التكامل بالتعويض: نختار $u$ (غالبًا ما داخل القوس أو الجذر أو الأس، بحيث تظهر مشتقته في التكامل)، نحسب $du$ ، نحوّل التكامل كله إلى $u$ ، نكامل، ثم نرجع إلى $x$"
SUBD = r"في التكامل المحدود بالتعويض نغيّر الحدود أيضًا: نعوّض كل حدّ من حدود $x$ في علاقة $u$ ، فلا نحتاج إلى الرجوع إلى $x$"
PARTS = r"التكامل بالأجزاء: $\displaystyle\int u\,dv=uv-\int v\,du$ ، ونختار $u$ الحدّ الذي يصبح أبسط بالاشتقاق ($\ln x$ أولًا، ثم كثير الحدود، ثم المثلثي أو الأسّي)"
FTC = r"التكامل المحدود: نجد الاقتران الأصلي $F$ ، ثم $\displaystyle\int_a^bf(x)\,dx=F(b)-F(a)$ (نعوّض الحدّ العلوي ثم نطرح تعويض الحدّ السفلي)"
CHECK = r"للتحقّق من أيّ تكامل غير محدود: اشتقّي الناتج، فيجب أن يعطي المقدار الذي داخل التكامل."
SEP = r"المعادلة التفاضلية القابلة للفصل: نضع كل ما فيه $y$ مع $dy$ في طرف، وكل ما فيه $x$ مع $dx$ في الطرف الآخر، ثم نكامل الطرفين ونضيف ثابتًا واحدًا $C$"
LOGD = r"إذا كان البسط مشتقة المقام: $\displaystyle\int\frac{g'(x)}{g(x)}\,dx=\ln|g(x)|+C$"
EKX = r"$\displaystyle\int e^{kx}\,dx=\frac{e^{kx}}{k}$ و $\displaystyle\int\cos kx\,dx=\frac{\sin kx}{k}$ و $\displaystyle\int\sin kx\,dx=-\frac{\cos kx}{k}$ (نقسم على معامل $x$)"
AX = r"تكامل الاقتران الأسّي: $\displaystyle\int a^{x}\,dx=\frac{a^{x}}{\ln a}+C$ ، وإذا كان الأس $kx+b$ نقسم أيضًا على معامل $x$: $\displaystyle\int a^{kx+b}\,dx=\frac{a^{kx+b}}{k\ln a}+C$"
TRIG = r"تكاملات مثلثية أساسية: $\displaystyle\int\sec^2x\,dx=\tan x$ ، $\displaystyle\int\csc^2x\,dx=-\cot x$ ، $\displaystyle\int\sec x\tan x\,dx=\sec x$ ، $\displaystyle\int\csc x\cot x\,dx=-\csc x$"
TANCOT = r"$\displaystyle\int\tan x\,dx=-\ln|\cos x|+C$ و $\displaystyle\int\cot x\,dx=\ln|\sin x|+C$ (البسط مشتقة المقام أو سالبها)"
PYTH = r"متطابقات فيثاغورس: $\sin^2x+\cos^2x=1$ ، $1+\tan^2x=\sec^2x$ ، $1+\cot^2x=\csc^2x$"
POWRED = r"تقليص القوة: $\sin^2x=\dfrac{1-\cos2x}{2}$ و $\cos^2x=\dfrac{1+\cos2x}{2}$"
WASH = r"الحجم الدوراني حول المحور $x$: $V=\pi\displaystyle\int_a^b \big(f(x)\big)^2\,dx$ ، وبين منحنيين (طريقة الحلقات): $V=\pi\displaystyle\int_a^b\left(R^2-r^2\right)dx$ حيث $R$ البعيد عن المحور و $r$ القريب"
DIST = r"الإزاحة هي $\displaystyle\int v\,dt$ ، أما المسافة الكلية فهي $\displaystyle\int|v|\,dt$: نقسم الفترة عند أصفار $v$ ، نكامل كل جزء وحده، ثم نجمع القيم المطلقة"
POS = r"الموقع بعد زمن $t$: $s(t)=s(0)+\displaystyle\int_0^t v\,dt$ ، أي الموقع الابتدائي + الإزاحة"
VTG = r"من منحنى السرعة – الزمن: الإزاحة = المساحة فوق محور $t$ − المساحة تحته، والمسافة = مجموع المساحتين، والموقع النهائي = الموقع الابتدائي + الإزاحة"
PFR = r"الكسور الجزئية: نحلّل المقام، نكتب كسرًا لكل عامل، نضرب الطرفين في المقام، ثم نعوّض بأصفار العوامل لإيجاد الثوابت؛ وتكامل $\dfrac{A}{x-a}$ هو $A\ln|x-a|$"
IMPROPER = r"إذا كانت درجة البسط أكبر من درجة المقام أو تساويها (كسر غير فعلي) نقسم أولًا: البسط = المقام × ناتج القسمة + الباقي"
AREA = r"المساحة بين منحنيين: نجد نقاط التقاطع (حدود التكامل)، نحدّد المنحنى الأعلى بتجربة نقطة بينهما، ثم نكامل (الأعلى − الأسفل)"
AREA0 = r"المساحة بين منحنى والمحور $x$: إذا كان المنحنى فوق المحور فالمساحة $\displaystyle\int_a^bf(x)\,dx$ ، وإذا كان تحته نأخذ القيمة المطلقة للتكامل (المساحة لا تكون سالبة)"
INIT = r"إيجاد الاقتران من مشتقته: نكامل فنحصل على الاقتران مع ثابت $C$ ، ثم نعوّض النقطة المعطاة (أو القيمة الابتدائية) لإيجاد $C$"
OPTCHECK = r"يمكنك أيضًا التحقّق من البدائل: الصحيح يحقّق الشرطين معًا (مشتقته تساوي المعطى، ويمرّ بالنقطة)."
